<?php
namespace Database\Seeders;use App\Core\Skills\{SkillFrontmatter,SourceProvenanceValidator};use App\Models\Skill;use Illuminate\Database\Seeder;
class DatabaseSeeder extends Seeder {public function run():void{$meta=['b2b-sales-agent'=>['source'=>'https://github.com/LiChang1125/B2B_Sales_Agent_Skill','license'=>'MIT'],'gtm-agents-starter'=>['source'=>'https://github.com/gtmagents/gtm-agents','license'=>'Apache-2.0'],'goose-growth-starter'=>['source'=>'https://github.com/gooseworks-ai/goose-skills','license'=>'MIT']];foreach($meta as $slug=>$source){$file=base_path("skills/builtin/{$slug}/SKILL.md");if(!is_file($file))continue;$content=(string)file_get_contents($file);$parsed=SkillFrontmatter::parse($content);Skill::withoutGlobalScopes()->updateOrCreate(['workspace_id'=>null,'slug'=>$slug],['name'=>$parsed['name'],'description'=>$parsed['description'],'version'=>$parsed['version'],'source_type'=>'builtin','source_url'=>$source['source'],'source_ref'=>'main','checksum'=>SourceProvenanceValidator::checksum($content),'license'=>$source['license'],'capabilities'=>$parsed['capabilities'],'body'=>$parsed['body'],'status'=>'active','built_in'=>true]);}}}
